rest.assertionCode:
def assert_response(responseBody, globalParam, statusCode, headers):
    if statusCode != 200 or not isinstance(responseBody, dict) or responseBody.get("code") != 0:
        raise Blocked("社区准备请求失败")
    data = responseBody.get("data")
    if not isinstance(data, list) or len(data) == 0 or not data[0].get("id"):
        raise Blocked("无可用社区；公开 HTTP 无社区创建接口")
    assert responseBody.get("requestId")
    return True

def assert_response(responseBody, globalParam, statusCode, headers):
    if statusCode == 409:
        raise Blocked("指定邮箱已有身份，不删除已有账号")
    if statusCode != 200 or not isinstance(responseBody, dict) or responseBody.get("code") != 0:
        raise Blocked("独立注册失败，停止业务并清理已创建用户")
    assert responseBody.get("requestId")
    data = responseBody["data"]
    assert data["user"]["id"] and data["user"]["nickname"] == "测试用户A"
    assert data["user"]["communityId"] == globalParam["COMMUNITY_A"]
    assert data["accessToken"] and data["refreshToken"]
    expires = data.get("expiresIn")
    if not isinstance(expires, int) or isinstance(expires, bool) or expires <= 0:
        raise Blocked("expiresIn 缺失或非法，无法安排自然过期等待")
    if expires > 2592000:
        raise Blocked("expiresIn 超过单次等待上限 30 天")
    return True

def assert_response(responseBody, globalParam, statusCode, headers):
    if statusCode != 401 or not isinstance(responseBody, dict) or responseBody.get("code") != 40101:
        return False
    if not isinstance(responseBody.get("requestId"), str) or not responseBody["requestId"]:
        return False
    if not set(responseBody.keys()) <= {"code", "message", "data", "requestId"}:
        return False
    if responseBody.get("data") not in (None, {}):
        return False
    pending = [responseBody]
    while pending:
        value = pending.pop()
        if isinstance(value, dict):
            for key, child in value.items():
                if key in ("id", "nickname", "communityId", "gender", "birthDate", "avatarUrl", "status", "communityChangedAt") and child:
                    return False
                pending.append(child)
        elif isinstance(value, list):
            pending.extend(value)
    return True

def assert_response(responseBody, globalParam, statusCode, headers):
    if not isinstance(responseBody, dict):
        raise Blocked("刷新响应不可解析，续期前提不满足")
    if statusCode == 401 and responseBody.get("code") == 40101:
        raise Blocked("等待期间刷新令牌已失效，续期前提不满足")
    if statusCode != 200 or responseBody.get("code") != 0:
        raise Blocked("刷新未成功，续期前提不满足")
    assert responseBody.get("requestId")
    data = responseBody["data"]
    assert data["user"]["id"] == globalParam["USER_A"]
    assert data["accessToken"] and data["refreshToken"]
    return True

def assert_response(responseBody, globalParam, statusCode, headers):
    assert responseBody.get("requestId")
    if statusCode == 200 and responseBody["code"] == 0:
        assert responseBody["data"]["id"] == globalParam["USER_A"]
        return True
    return statusCode == 401 and responseBody["code"] == 40101

def assert_response(responseBody, globalParam, statusCode, headers):
    assert statusCode == 200 and responseBody["code"] == 0
    assert responseBody.get("requestId")
    return responseBody["data"] == {}
